"""Test all robot commands — runs each command and prints telemetry to verify."""
"""This was generated by AI based on the other examples, to cover all commands and some error cases."""

import sys
import os
import time

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

from robomotionsim_client import Robot
from robomotionsim_client.robot import RobotCommandError

robot = Robot("tcp://localhost:5555", "tcp://localhost:5556")
robot.connect()
print("Connected to simulation\n")

passed = 0
failed = 0


def status():
    robot.run()
    return (f"x={robot.get_distance_traveled_x():.1f} "
            f"y={robot.get_distance_traveled_y():.1f} "
            f"angle={robot.get_chassis_angle():.1f}")


def test(name, fn, check=None):
    global passed, failed
    print(f"[TEST] {name}")
    before = status()
    try:
        fn()
        after = status()
        if check:
            ok, msg = check()
            if ok:
                print(f"  PASS — {msg}")
                passed += 1
            else:
                print(f"  FAIL — {msg}")
                failed += 1
        else:
            print(f"  DONE — before: {before}")
            print(f"         after:  {after}")
            passed += 1
    except Exception as e:
        print(f"  FAIL — {e}")
        failed += 1
    print()


def test_expect_error(name, fn):
    """Test that expects an error from the simulator (CMD_ERROR)."""
    global passed, failed
    print(f"[TEST] {name}")
    try:
        fn()
        # If we get here with no exception, the command was accepted but may
        # still fail — drain messages briefly to catch CMD_ERROR
        start = time.monotonic()
        while time.monotonic() - start < 1.0:
            robot.run()
            time.sleep(0.02)
        print(f"  FAIL — expected error but command succeeded")
        failed += 1
    except (RobotCommandError, Exception) as e:
        print(f"  PASS — got expected error: {e}")
        passed += 1
    print()


