# 43. stop interrupts current command
def test_stop_interrupt():
    x0 = robot.get_distance_traveled_x()
    robot.move_by_distance_raw(distance_mm=10000, x_speed=200, y_speed=0,
                               rotation_speed=0, front_rotation_speed=0)
    start = time.monotonic()
    while time.monotonic() - start < 0.3:
        robot.run()
        time.sleep(0.02)
    robot.stop()
    robot.run_to_position()

def check_stop_interrupt():
    return (True, f"x={robot.get_distance_traveled_x():.1f} (should be much less than 10000)")

test("stop — interrupt a 10000mm move after 0.3s", test_stop_interrupt, check_stop_interrupt)


