# 49. All telemetry getters
def test_telemetry():
    robot.move_by_distance_raw(distance_mm=100, x_speed=80, y_speed=0,
                               rotation_speed=0, front_rotation_speed=0)
    robot.run_to_position()
    robot.run()
    print(f"  distance_x        = {robot.get_distance_traveled_x():.1f}")
    print(f"  distance_y        = {robot.get_distance_traveled_y():.1f}")
    print(f"  velocity_x        = {robot.get_velocity_x():.1f}")
    print(f"  velocity_y        = {robot.get_velocity_y():.1f}")
    print(f"  front_angle       = {robot.get_front_angle():.1f}")
    print(f"  chassis_angle     = {robot.get_chassis_angle():.1f}")
    print(f"  angular_velocity  = {robot.get_chassis_angular_velocity():.1f}")
    for i in range(3):
        print(f"  wheel {i} speed={robot.get_wheel_speed(i):.1f} "
              f"dist={robot.get_wheel_distance(i):.1f}")

test("telemetry — all getters after 100mm move", test_telemetry)


